  "created_at" TEXT NOT NULL,
  CONSTRAINT "pk_auto_actions" PRIMARY KEY ("action_id"),
  CONSTRAINT "ck_auto_actions_enabled" CHECK (enabled IN (0, 1)),
  CONSTRAINT "ck_auto_actions_filter_json" CHECK (filter_json IS NULL OR json_valid(filter_json, 8)),
  CONSTRAINT "ck_auto_actions_trigger" CHECK (trigger IN ('note-created', 'note-updated', 'notebook-created'))
) STRICT;

-- One row per physical page of an imported document (design-docs/specs/note-store-schema-v25.md).
-- Page versions are a closed set: original = origin_file_id + page_number, ocr = text / text_status / text_source, translated = note_translations.
CREATE TABLE "document_pages" (
  "note_id" TEXT NOT NULL,
  -- The original: the retained PDF (all pages share it) or the page image.
  "origin_file_id" TEXT NOT NULL,
  -- Physical page number within the original, starting at 1.
  "page_number" INTEGER NOT NULL,
  -- PDFs only: prefer embedded text or OCR only.
  "text_extraction_mode" TEXT,
  -- The OCR version: native PDF text or OCR output, plain text. Empty while pending.
  "text" TEXT NOT NULL DEFAULT '',
  "text_status" TEXT NOT NULL,
  -- pdf-text or ocr; set exactly when text_status is complete.
  "text_source" TEXT,
  -- Page analysis: language, writing mode, binding, title.
  "analysis_json" BLOB NOT NULL,
  CONSTRAINT "pk_document_pages" PRIMARY KEY ("note_id"),
  CONSTRAINT "ck_document_pages_analysis_json" CHECK (json_valid(analysis_json, 8)),
  CONSTRAINT "ck_document_pages_complete_has_source" CHECK ((text_status = 'complete') = (text_source IS NOT NULL)),
  CONSTRAINT "ck_document_pages_page_number" CHECK (page_number >= 1),
  CONSTRAINT "ck_document_pages_text_extraction_mode" CHECK (text_extraction_mode IS NULL OR text_extraction_mode IN ('prefer-pdf-text', 'ocr-only')),
  CONSTRAINT "ck_document_pages_text_source" CHECK (text_source IS NULL OR text_source IN ('pdf-text', 'ocr')),
  CONSTRAINT "ck_document_pages_text_status" CHECK (text_status IN ('pending', 'complete')),
  CONSTRAINT "fk_document_pages_note_id_notes" FOREIGN KEY ("note_id") REFERENCES "notes" ("note_id") ON DELETE CASCADE,
  CONSTRAINT "fk_document_pages_origin_file_id_files" FOREIGN KEY ("origin_file_id") REFERENCES "files" ("file_id")
) STRICT;

-- Stored file content. Exactly one locator per storage kind: a migrated row drops its local path, and a local row has no S3 coordinates.
CREATE TABLE "files" (
  "file_id" TEXT NOT NULL,
  "storage_kind" TEXT NOT NULL,
  "local_path" TEXT,
  "s3_profile" TEXT,
  "s3_bucket" TEXT,
  "s3_key" TEXT,
  "media_type" TEXT NOT NULL,
  "byte_size" INTEGER NOT NULL,
  "sha256" TEXT NOT NULL,
  "original_filename" TEXT,
  "created_at" TEXT NOT NULL,
  "migrated_at" TEXT,
  CONSTRAINT "pk_files" PRIMARY KEY ("file_id"),
  CONSTRAINT "ck_files_byte_size" CHECK (byte_size >= 0),
  CONSTRAINT "ck_files_locator" CHECK ((storage_kind = 'local' AND local_path IS NOT NULL AND s3_profile IS NULL AND s3_bucket IS NULL AND s3_key IS NULL) OR (storage_kind = 's3' AND local_path IS NULL AND s3_profile IS NOT NULL AND s3_bucket IS NOT NULL AND s3_key IS NOT NULL)),
  CONSTRAINT "ck_files_storage_kind" CHECK (storage_kind IN ('local', 's3'))
) STRICT;

-- Groups of notebooks (design-docs/specs/library.md). auth_required = 0 means anyone may reach the library.
CREATE TABLE "libraries" (
  "library_id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "auth_required" INTEGER NOT NULL DEFAULT 1,
  "is_default" INTEGER NOT NULL DEFAULT 0,
  "created_at" TEXT NOT NULL,
  "created_by" TEXT,
  CONSTRAINT "pk_libraries" PRIMARY KEY ("library_id"),
  CONSTRAINT "ck_libraries_auth_required" CHECK (auth_required IN (0, 1)),
  CONSTRAINT "ck_libraries_is_default" CHECK (is_default IN (0, 1)),
  CONSTRAINT "fk_libraries_created_by_users" FOREIGN KEY ("created_by") REFERENCES "users" ("user_id")
) STRICT;

-- Which authenticated users may reach a library that requires authentication.
CREATE TABLE "library_members" (
  "library_id" TEXT NOT NULL,
  "user_id" TEXT NOT NULL,
  "role" TEXT NOT NULL DEFAULT 'member',
  "granted_at" TEXT NOT NULL,
  "granted_by" TEXT,
  CONSTRAINT "pk_library_members" PRIMARY KEY ("library_id", "user_id"),
  CONSTRAINT "ck_library_members_role" CHECK (role IN ('owner', 'member')),
  CONSTRAINT "fk_library_members_granted_by_users" FOREIGN KEY ("granted_by") REFERENCES "users" ("user_id"),
  CONSTRAINT "fk_library_members_library_id_libraries" FOREIGN KEY ("library_id") REFERENCES "libraries" ("library_id"),
  CONSTRAINT "fk_library_members_user_id_users" FOREIGN KEY ("user_id") REFERENCES "users" ("user_id")
) STRICT, WITHOUT ROWID;

-- Append-only per-actor action history behind undo/redo (design-docs/specs/action-history-undo.md). AUTOINCREMENT keeps seq monotonic across retention pruning; action names are owned by the code that writes them.
CREATE TABLE "note_action_log" (
  "seq" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  "occurred_at" TEXT NOT NULL,
  "actor_user_id" TEXT NOT NULL,
  "provenance" TEXT NOT NULL,
  "entity_type" TEXT NOT NULL,
  "entity_id" TEXT NOT NULL,
  "notebook_id" TEXT,
  "action" TEXT NOT NULL,
  "display_json" BLOB NOT NULL,
  "delta_json" BLOB,
  "undoable" INTEGER NOT NULL,
  "undo_of_seq" INTEGER,
  "undone_by_seq" INTEGER,
  CONSTRAINT "ck_note_action_log_delta_json" CHECK (delta_json IS NULL OR json_valid(delta_json, 8)),
  CONSTRAINT "ck_note_action_log_display_json" CHECK (json_valid(display_json, 8)),
  CONSTRAINT "ck_note_action_log_entity_type" CHECK (entity_type IN ('note', 'notebook', 'comment')),
  CONSTRAINT "ck_note_action_log_provenance" CHECK (provenance IN ('human', 'ai', 'system')),
  CONSTRAINT "ck_note_action_log_undoable" CHECK (undoable IN (0, 1)),
  CONSTRAINT "fk_note_action_log_actor_user_id_users" FOREIGN KEY ("actor_user_id") REFERENCES "users" ("user_id")
) STRICT;

-- Memos attach to a note, to a whole notebook, or both (a note memo also records its notebook so notebook-wide listings need no join).
CREATE TABLE "note_comments" (
  "comment_id" TEXT NOT NULL,
  "note_id" TEXT,
  "notebook_id" TEXT,
  "body_markdown" TEXT NOT NULL,
  "author" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  CONSTRAINT "pk_note_comments" PRIMARY KEY ("comment_id"),
  CONSTRAINT "ck_note_comments_anchor" CHECK (note_id IS NOT NULL OR notebook_id IS NOT NULL),
  CONSTRAINT "fk_note_comments_note_id_notes" FOREIGN KEY ("note_id") REFERENCES "notes" ("note_id"),
  CONSTRAINT "fk_note_comments_notebook_id_notebooks" FOREIGN KEY ("notebook_id") REFERENCES "notebooks" ("notebook_id")
) STRICT;

-- Files attached to a note.
CREATE TABLE "note_files" (
  "note_id" TEXT NOT NULL,
  "file_id" TEXT NOT NULL,
  "role" TEXT NOT NULL,
  "position" INTEGER NOT NULL DEFAULT 0,
  CONSTRAINT "pk_note_files" PRIMARY KEY ("note_id", "file_id", "role"),
  CONSTRAINT "ck_note_files_role" CHECK (role IN ('embedded', 'related', 'source-page-image')),
  CONSTRAINT "fk_note_files_file_id_files" FOREIGN KEY ("file_id") REFERENCES "files" ("file_id"),
  CONSTRAINT "fk_note_files_note_id_notes" FOREIGN KEY ("note_id") REFERENCES "notes" ("note_id")
) STRICT, WITHOUT ROWID;

-- Maps note_fts rows to notes. The FTS table is contentless, so a 'delete' must repeat the exact values that were inserted; the context payload is stored here because tag ancestry can change after indexing.
CREATE TABLE "note_fts_map" (
  "fts_rowid" INTEGER NOT NULL,
  "note_id" TEXT NOT NULL,
  "context" TEXT NOT NULL DEFAULT '',
  CONSTRAINT "pk_note_fts_map" PRIMARY KEY ("fts_rowid"),
  CONSTRAINT "fk_note_fts_map_note_id_notes" FOREIGN KEY ("note_id") REFERENCES "notes" ("note_id")
) STRICT;

-- Directed links between notes.
CREATE TABLE "note_links" (
  "from_note_id" TEXT NOT NULL,
  "to_note_id" TEXT NOT NULL,
  "link_kind" TEXT NOT NULL DEFAULT 'related',
  "provenance" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  CONSTRAINT "pk_note_links" PRIMARY KEY ("from_note_id", "to_note_id", "link_kind"),
  CONSTRAINT "ck_note_links_provenance" CHECK (provenance IN ('human', 'ai', 'system')),
  CONSTRAINT "fk_note_links_from_note_id_notes" FOREIGN KEY ("from_note_id") REFERENCES "notes" ("note_id"),
  CONSTRAINT "fk_note_links_to_note_id_notes" FOREIGN KEY ("to_note_id") REFERENCES "notes" ("note_id")
) STRICT, WITHOUT ROWID;

-- Schema versions applied to this store. v25 has no upgrade paths: an older store is rejected.
CREATE TABLE "note_schema_version" (
  "version" INTEGER NOT NULL,
  "applied_at" TEXT NOT NULL,
  CONSTRAINT "pk_note_schema_version" PRIMARY KEY ("version")
) STRICT;

-- Tag assignments of notes.
CREATE TABLE "note_tags" (
  "note_id" TEXT NOT NULL,
  "tag_id" TEXT NOT NULL,
  "provenance" TEXT NOT NULL,
  "assigned_by" TEXT,
  "deletable" INTEGER NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL,
  CONSTRAINT "pk_note_tags" PRIMARY KEY ("note_id", "tag_id"),
  CONSTRAINT "ck_note_tags_deletable" CHECK (deletable IN (0, 1)),
  CONSTRAINT "ck_note_tags_provenance" CHECK (provenance IN ('human', 'ai', 'system')),
  CONSTRAINT "fk_note_tags_note_id_notes" FOREIGN KEY ("note_id") REFERENCES "notes" ("note_id"),
  CONSTRAINT "fk_note_tags_tag_id_tags" FOREIGN KEY ("tag_id") REFERENCES "tags" ("tag_id")
) STRICT, WITHOUT ROWID;

-- The Translated version of a note: one body per note and language, replaced in place when the source text changes.
CREATE TABLE "note_translations" (
  "note_id" TEXT NOT NULL,
  -- Target language as requested, trimmed.
  "language" TEXT NOT NULL,
  "body" TEXT NOT NULL,
  -- Hash of the source text this translation was made from; a mismatch marks it outdated.
  "source_sha256" TEXT NOT NULL,
  "provenance" TEXT NOT NULL,
  "created_by" TEXT,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  CONSTRAINT "pk_note_translations" PRIMARY KEY ("note_id", "language"),
  CONSTRAINT "ck_note_translations_language" CHECK (length(trim(language)) > 0),
  CONSTRAINT "ck_note_translations_provenance" CHECK (provenance IN ('human', 'ai', 'system')),
  CONSTRAINT "fk_note_translations_created_by_users" FOREIGN KEY ("created_by") REFERENCES "users" ("user_id"),
  CONSTRAINT "fk_note_translations_note_id_notes" FOREIGN KEY ("note_id") REFERENCES "notes" ("note_id") ON DELETE CASCADE
) STRICT;

-- Files attached to a notebook; an imported document's original is its source-document.
CREATE TABLE "notebook_files" (
  "notebook_id" TEXT NOT NULL,
  "file_id" TEXT NOT NULL,
  "role" TEXT NOT NULL,
  CONSTRAINT "pk_notebook_files" PRIMARY KEY ("notebook_id", "file_id", "role"),
  CONSTRAINT "ck_notebook_files_role" CHECK (role IN ('source-document', 'related')),
  CONSTRAINT "fk_notebook_files_file_id_files" FOREIGN KEY ("file_id") REFERENCES "files" ("file_id"),
  CONSTRAINT "fk_notebook_files_notebook_id_notebooks" FOREIGN KEY ("notebook_id") REFERENCES "notebooks" ("notebook_id")
) STRICT, WITHOUT ROWID;

-- Per-notebook content revision, incremented by every recorded notebook change and by page OCR completion. A translation pass completes only while it is unchanged. Kept outside the prunable action log.
CREATE TABLE "notebook_revisions" (
  "notebook_id" TEXT NOT NULL,
  "revision" INTEGER NOT NULL,
  CONSTRAINT "pk_notebook_revisions" PRIMARY KEY ("notebook_id"),
  CONSTRAINT "ck_notebook_revisions_revision" CHECK (revision >= 0),
  CONSTRAINT "fk_notebook_revisions_notebook_id_notebooks" FOREIGN KEY ("notebook_id") REFERENCES "notebooks" ("notebook_id") ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

-- Tag assignments of notebooks, including notebook-kind:* system tags.
CREATE TABLE "notebook_tags" (
  "notebook_id" TEXT NOT NULL,
  "tag_id" TEXT NOT NULL,
  "provenance" TEXT NOT NULL,
  "assigned_by" TEXT,
  "deletable" INTEGER NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL,
  CONSTRAINT "pk_notebook_tags" PRIMARY KEY ("notebook_id", "tag_id"),
  CONSTRAINT "ck_notebook_tags_deletable" CHECK (deletable IN (0, 1)),
  CONSTRAINT "ck_notebook_tags_provenance" CHECK (provenance IN ('human', 'ai', 'system')),
  CONSTRAINT "fk_notebook_tags_notebook_id_notebooks" FOREIGN KEY ("notebook_id") REFERENCES "notebooks" ("notebook_id"),
  CONSTRAINT "fk_notebook_tags_tag_id_tags" FOREIGN KEY ("tag_id") REFERENCES "tags" ("tag_id")
) STRICT, WITHOUT ROWID;

-- A notebook belongs to one library and one owner.
CREATE TABLE "notebooks" (
  "notebook_id" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "read_only" INTEGER NOT NULL DEFAULT 0,
  "owner_user_id" TEXT NOT NULL,
  "library_id" TEXT NOT NULL DEFAULT 'library-default',
  "created_by" TEXT,
  "updated_by" TEXT,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  "meta_json" BLOB,
  CONSTRAINT "pk_notebooks" PRIMARY KEY ("notebook_id"),
  CONSTRAINT "ck_notebooks_meta_json" CHECK (meta_json IS NULL OR json_valid(meta_json, 8)),
  CONSTRAINT "ck_notebooks_read_only" CHECK (read_only IN (0, 1)),
  CONSTRAINT "fk_notebooks_created_by_users" FOREIGN KEY ("created_by") REFERENCES "users" ("user_id"),
  CONSTRAINT "fk_notebooks_library_id_libraries" FOREIGN KEY ("library_id") REFERENCES "libraries" ("library_id"),
  CONSTRAINT "fk_notebooks_owner_user_id_users" FOREIGN KEY ("owner_user_id") REFERENCES "users" ("user_id"),
  CONSTRAINT "fk_notebooks_updated_by_users" FOREIGN KEY ("updated_by") REFERENCES "users" ("user_id")
) STRICT;

-- Notes. For an imported document page the note is the anchor of its versions, memos, tags, links and AI discussion; the page itself lives in document_pages.
CREATE TABLE "notes" (
  "note_id" TEXT NOT NULL,
  "notebook_id" TEXT NOT NULL,
  -- Position in the notebook; for a document page it equals the physical page number.
  "note_number" INTEGER NOT NULL,
  "title" TEXT,
  "title_source" TEXT NOT NULL DEFAULT 'derived',
  "body_markdown" TEXT NOT NULL,
  "read_only" INTEGER NOT NULL DEFAULT 0,
  "created_by" TEXT,
  "updated_by" TEXT,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  "meta_json" BLOB,
  CONSTRAINT "pk_notes" PRIMARY KEY ("note_id"),
  CONSTRAINT "ck_notes_meta_json" CHECK (meta_json IS NULL OR json_valid(meta_json, 8)),
  CONSTRAINT "ck_notes_read_only" CHECK (read_only IN (0, 1)),
  CONSTRAINT "ck_notes_title_source" CHECK (title_source IN ('derived', 'explicit')),
  CONSTRAINT "fk_notes_created_by_users" FOREIGN KEY ("created_by") REFERENCES "users" ("user_id"),
  CONSTRAINT "fk_notes_notebook_id_notebooks" FOREIGN KEY ("notebook_id") REFERENCES "notebooks" ("notebook_id"),
  CONSTRAINT "fk_notes_updated_by_users" FOREIGN KEY ("updated_by") REFERENCES "users" ("user_id")
) STRICT;

-- The external search engine index this store is synchronized with (singleton row).
CREATE TABLE "search_engine_sync_state" (
  "id" INTEGER NOT NULL,
  "index_identity" TEXT NOT NULL,
  "activated_at" TEXT NOT NULL,
  CONSTRAINT "pk_search_engine_sync_state" PRIMARY KEY ("id"),
  CONSTRAINT "ck_search_engine_sync_state_singleton" CHECK (id = 1)
) STRICT;

-- Notes whose external search engine document must be written or deleted. note_id has no foreign key: deleted notes stay queued so their documents are removed.
CREATE TABLE "search_index_outbox" (
  "note_id" TEXT NOT NULL,
  "generation" INTEGER NOT NULL DEFAULT 1,
  "attempts" INTEGER NOT NULL DEFAULT 0,
  "next_attempt_at" TEXT,
  "last_error" TEXT,
  "claim_token" TEXT,
  "claimed_until" TEXT,
  CONSTRAINT "pk_search_index_outbox" PRIMARY KEY ("note_id")
) STRICT;

-- Ontology classes of tags (Date, Name, Place, ...).
CREATE TABLE "tag_classes" (
  "class_id" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  "description" TEXT,
  "is_system" INTEGER NOT NULL DEFAULT 0,
  "created_at" TEXT NOT NULL,
  CONSTRAINT "pk_tag_classes" PRIMARY KEY ("class_id"),
  CONSTRAINT "ck_tag_classes_is_system" CHECK (is_system IN (0, 1))
) STRICT;

-- Tags. Folder tags form a tree through parent_tag_id; other tag names are unique.
CREATE TABLE "tags" (
  "tag_id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "class_id" TEXT,
  "parent_tag_id" TEXT,
  "is_system" INTEGER NOT NULL DEFAULT 0,
  -- The note that describes this tag (E1). A column, so one note per tag is the schema's job; ON DELETE SET NULL clears it, and undo restores it from the deletion snapshot.
  "canonical_note_id" TEXT,
  "created_at" TEXT NOT NULL,
  CONSTRAINT "pk_tags" PRIMARY KEY ("tag_id"),
  CONSTRAINT "ck_tags_is_system" CHECK (is_system IN (0, 1)),
  CONSTRAINT "fk_tags_canonical_note_id_notes" FOREIGN KEY ("canonical_note_id") REFERENCES "notes" ("note_id") ON DELETE SET NULL,
  CONSTRAINT "fk_tags_class_id_tag_classes" FOREIGN KEY ("class_id") REFERENCES "tag_classes" ("class_id"),
  CONSTRAINT "fk_tags_parent_tag_id_tags" FOREIGN KEY ("parent_tag_id") REFERENCES "tags" ("tag_id")
) STRICT;

-- One translation request: notebook, target language, optional inclusive page range, status, and the cursor and pass revision that let an outbox retry resume.
CREATE TABLE "translation_jobs" (
  "job_id" TEXT NOT NULL,
  "notebook_id" TEXT NOT NULL,
  "target_language" TEXT NOT NULL,
  "page_start" INTEGER,
  "page_end" INTEGER,
  "status" TEXT NOT NULL DEFAULT 'pending',
  "error_message" TEXT,
  -- Last note of the current pass known to be translated; NULL restarts the pass.
  "continuation_note_id" TEXT,
  -- notebook_revisions.revision captured when the current pass began.
  "source_revision" INTEGER,
  "requested_by" TEXT,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  CONSTRAINT "pk_translation_jobs" PRIMARY KEY ("job_id"),
  CONSTRAINT "ck_translation_jobs_page_range" CHECK ((page_start IS NULL AND page_end IS NULL) OR (page_start >= 1 AND page_end >= page_start)),
  CONSTRAINT "ck_translation_jobs_status" CHECK (status IN ('pending', 'completed', 'failed', 'cancelled')),
  CONSTRAINT "ck_translation_jobs_target_language" CHECK (length(trim(target_language)) > 0),
  CONSTRAINT "fk_translation_jobs_continuation_note_id_notes" FOREIGN KEY ("continuation_note_id") REFERENCES "notes" ("note_id") ON DELETE SET NULL,
  CONSTRAINT "fk_translation_jobs_notebook_id_notebooks" FOREIGN KEY ("notebook_id") REFERENCES "notebooks" ("notebook_id") ON DELETE CASCADE,
  CONSTRAINT "fk_translation_jobs_requested_by_users" FOREIGN KEY ("requested_by") REFERENCES "users" ("user_id")
) STRICT;

-- One personal-agent provider credential per user. The key is never selected by any caller-facing read path.
CREATE TABLE "user_agent_credentials" (
  "user_id" TEXT NOT NULL,
  "provider" TEXT NOT NULL,
  "api_key" TEXT NOT NULL,
  "base_url" TEXT,
  "default_model" TEXT NOT NULL,
  "enabled" INTEGER NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  CONSTRAINT "pk_user_agent_credentials" PRIMARY KEY ("user_id"),
  CONSTRAINT "ck_user_agent_credentials_enabled" CHECK (enabled IN (0, 1)),
  CONSTRAINT "ck_user_agent_credentials_provider" CHECK (provider IN ('anthropic', 'openai', 'openrouter', 'openai-compatible', 'codex')),
  CONSTRAINT "fk_user_agent_credentials_user_id_users" FOREIGN KEY ("user_id") REFERENCES "users" ("user_id")
) STRICT;

-- Accounts. Every notebook has a real owner rather than a null "everyone".
-- SQLite treats NULLs as distinct in a UNIQUE index, so any number of accounts may lack an email.
CREATE TABLE "users" (
  "user_id" TEXT NOT NULL,
  "email" TEXT,
  "display_name" TEXT NOT NULL,
  "is_default" INTEGER NOT NULL DEFAULT 0,
  "is_admin" INTEGER NOT NULL DEFAULT 0,
  "created_at" TEXT NOT NULL,
  "disabled_at" TEXT,
  CONSTRAINT "pk_users" PRIMARY KEY ("user_id"),
  CONSTRAINT "ck_users_is_admin" CHECK (is_admin IN (0, 1)),
